# ---------------------------------------------------------------------------
# AUTO-GENERATED by Claude Code
# Purpose: the app's "desktop": the picture shown when no panel is open (ui.desktop). Which
#          file that is comes from the app's settings (config.background; by default Omarchy's
#          link to the current theme's background, so the app follows the desktop around it).
#          Read from disk on every request (no cache): a new setting or theme shows at once.
# Usage: GET /background (mounted in api.py) -> the picture, or 404 when this machine has none
#        (the view then keeps its plain dark background).
# ---------------------------------------------------------------------------
from __future__ import annotations

from typing import TYPE_CHECKING

from starlette.responses import FileResponse, Response

from ui.config import config

if TYPE_CHECKING:
    from starlette.requests import Request


async def background(_: Request) -> Response:
    """The background as it is now; 404 when there is none (not Omarchy, or a broken link)."""
    picture = config.background.resolve()
    if not picture.is_file():
        return Response(status_code=404)
    # no-store: the browser asks again each time, so it never shows an old theme's picture
    return FileResponse(picture, headers={"Cache-Control": "no-store"})
